def _sha_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _sha_json(value: Any) -> str:
    return _sha_bytes(canonical_json(value).encode("utf-8"))


def _file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _safe_child(root: Path, relative: str, code: str) -> Path:
    if not isinstance(relative, str) or not relative or Path(relative).is_absolute():
        raise FailClosed(code)
    base = root.resolve()
    target = (base / relative).resolve()
    if os.path.commonpath((str(base), str(target))) != str(base):
        raise FailClosed(code)
    return target


def _boot_id() -> str:
    path = Path(os.environ.get("P5_BOOT_ID_FILE", "/proc/sys/kernel/random/boot_id"))
    try:
        value = path.read_text(encoding="ascii").strip()
    except OSError as exc:
        raise FailClosed("BOOT_ID_UNAVAILABLE") from exc
    if not value:
        raise FailClosed("BOOT_ID_UNAVAILABLE")
    return value


_TEST_CLOCK = 0


def _monotonic_ns() -> int:
    global _TEST_CLOCK
    step = os.environ.get("P5_TEST_MONOTONIC_STEP_NS")
    if step is not None:
        if os.environ.get("P5_SYNTHETIC_MODE") != "1":
            raise FailClosed("TEST_CLOCK_FORBIDDEN_OUTSIDE_SYNTHETIC_MODE")
        amount = int(step)
        if amount <= 0:
            raise FailClosed("TEST_CLOCK_STEP_INVALID")
        _TEST_CLOCK += amount
        return _TEST_CLOCK
    return time.monotonic_ns()


def _utc_now() -> str:
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


class PC6ExecutionAdapter:
    """Fixed-root adapter over ADMIN-STAGED canonical PC6 SOURCE bytes (FL20).

    F01 repair: the plan can no longer self-attest derived feature/outcome
    bytes.  The plan stages only canonical SOURCE objects; the TCB-pinned
    materializer (`pc6_alpha_materializer`) derives decision-time features
    outcome-blind, and derives horizon-specific outcome labels only inside
    the daemon after proposal APPLIED plus the durable label-access marker.
    No precomputed outcomes object may exist; its presence fails closed.
    """

    def __init__(self, bindings: FrozenBindings):
        self.bindings = bindings
        self.synthetic = os.environ.get("P5_SYNTHETIC_MODE") == "1"
        self.root = Path(os.environ.get("P5_EXECUTION_DATA_ROOT", "/data/k3/p5_execution_input"))
        self.plan_path = self.root / "P5_PC6_EXECUTION_ADAPTER_PLAN_V1.json"
        mat.assert_admin_immutable_root(
            self.root, "PC6_EXECUTION_ROOT_NOT_ADMIN_IMMUTABLE", self.synthetic)
        try:
            self.plan = json.loads(self.plan_path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise FailClosed("PC6_EXECUTION_PLAN_UNAVAILABLE") from exc
        if self.plan.get("schema") != "p5-pc6-execution-adapter-plan/v2":
            raise FailClosed("PC6_EXECUTION_PLAN_SCHEMA_MISMATCH")
        if not self.synthetic and self.plan.get("materialization_contract") != \
                "P5_PC6_EXECUTION_ADAPTER_CONTRACT_V2":
            raise FailClosed("PC6_EXECUTION_PLAN_CONTRACT_MISMATCH")
        if self.plan.get("dataset_manifest_sha256") != bindings.dataset_manifest_sha256:
            raise FailClosed("PC6_DATASET_BINDING_MISMATCH")
        if self.plan.get("revision_lineage_sha256") != bindings.revision_lineage_sha256:
            raise FailClosed("PC6_REVISION_BINDING_MISMATCH")
        runs = self.plan.get("runs")
        if not isinstance(runs, dict) or bindings.run_id not in runs:
            raise FailClosed("PC6_RUN_INPUT_UNAVAILABLE")
        self.run = runs[bindings.run_id]
        if not isinstance(self.run, dict) or self.run.get("cutoff") != bindings.cutoff:
            raise FailClosed("PC6_CUTOFF_MISMATCH")
        mat.enforce_frozen_cutoff(bindings.cutoff)
        forbidden = {"features_file", "features_sha256", "outcomes_file", "outcomes_sha256"}
        if forbidden & set(self.run):
            raise FailClosed("PC6_PRECOMPUTED_DERIVED_OBJECT_FORBIDDEN")
        self.kind = "W1" if bindings.wave_id is not None else "T1"
        self.scientific_root = Path(os.environ.get("P5_SCIENTIFIC_ROOT_DIR",
                                                   "/opt/p5/scientific-root-20"))
        self.source_path = mat.safe_relative_child(
            self.root, self.run.get("source_file"), "PC6_SOURCE_PATH_INVALID")
        if not self.synthetic:
            mat.assert_admin_immutable_file(
                self.plan_path, "PC6_EXECUTION_INPUT_NOT_ADMIN_IMMUTABLE", False)
        self._source: dict[str, Any] | None = None
        self._grid: list[int] | None = None
        self._features: dict[str, Any] | None = None
        self._evidence: dict[str, Any] | None = None

    def _header(self, with_pit: bool) -> dict[str, Any]:
        header = {
            "dataset_manifest_sha256": self.bindings.dataset_manifest_sha256,
            "revision_lineage_sha256": self.bindings.revision_lineage_sha256,
            "cutoff": self.bindings.cutoff,
        }
        if with_pit:
            header["pit_rule_sha256"] = self.bindings.universe_rule_sha256
        return header

    def _load(self) -> None:
        if self._evidence is not None:
            return
        source_sha = mat.verify_staged_object_file(
            self.root, self.run.get("source_file"), self.run.get("source_sha256"),
            self.synthetic, "PC6_SOURCE_OBJECT_INVALID")
        consumed = self.run.get("consumed_non_outcome_objects", [])
        if not isinstance(consumed, list):
            raise FailClosed("PC6_CONSUMED_OBJECTS_INVALID")
        if not self.synthetic and not consumed:
            raise FailClosed("PC6_CONSUMED_OBJECTS_REQUIRED")
        verified = []
        for item in consumed:
            if not isinstance(item, dict):
                raise FailClosed("PC6_CONSUMED_OBJECTS_INVALID")
            verified.append(mat.verify_staged_object_file(
                self.root, item.get("path"), item.get("sha256"),
                self.synthetic, "PC6_CONSUMED_OBJECT_HASH_MISMATCH"))
        staged = [source_sha, *verified]
        if not self.synthetic:
            manifest_path = self.scientific_root / "P5_PC6_EXECUTABLE_DATA_MANIFEST_V1.json"
            try:
                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            except (OSError, ValueError) as exc:
                raise FailClosed("PC6_FROZEN_MANIFEST_UNAVAILABLE") from exc
            mat.verify_staged_inventory_against_manifest(
                staged, mat.frozen_manifest_hash_set(manifest))
        source = mat.load_source(self.source_path.read_bytes())
        grid: list[int] = []
        for item in source["decision_grid_ts_utc"]:
            grid.append(mat.parse_utc_us(item) if isinstance(item, str) else int(item))
        grid_identity = mat.validate_decision_grid(grid, self.kind, self.synthetic)
        order = None
        candidates_by_id = None
        if self.kind == "W1":
            candidate_file = json.loads((self.scientific_root /
                "P5_P3_H0_DISCOVERY_WAVE1_CANDIDATE_LIST_V2.json").read_text(encoding="utf-8"))
            order = json.loads((self.scientific_root /
                "P5_P3_H0_WAVE1_EVALUATION_ORDER_SUBOBJECT_V1.json").read_text(encoding="utf-8"))
            candidates_by_id = {item["candidate_id"]: item
                                for item in candidate_file["candidates"]}
        features = mat.derive_features(source, grid, self.kind, self._header(True),
                                       candidates_by_id, order)
        self._source = source
        self._grid = grid
        self._features = features
        self._evidence = {
            "adapter_plan_sha256": _file_sha256(self.plan_path),
            "materializer_sha256": mat.materializer_sha256(),
            "source_sha256": source_sha,
            "consumed_non_outcome_sha256": verified,
            "staged_inventory_sha256": _sha_json(staged),
            "decision_grid": grid_identity,
            "derived_features_sha256": _sha_json(_json_safe(features)),
            "feature_schema": mat.FEATURES_SCHEMA,
            "outcome_schema": mat.OUTCOMES_SCHEMA + ":DAEMON_POST_MARKER_ON_DEMAND",
            "precomputed_outcomes_present": False,
            "outcomes_read": False,
        }

    def observe_outcome_free(self) -> dict[str, Any]:
        self._load()
        return dict(self._evidence)

    def load_features(self) -> dict[str, Any]:
        self._load()
        assert self._features is not None
        return self._features

    def derive_outcomes(self, marker_recorded: bool) -> dict[str, Any]:
        self._load()
        assert self._source is not None and self._grid is not None
        return mat.derive_outcomes(self._source, self._grid, self.kind,
                                   self._header(False), marker_recorded)


class AlphaExecutionEngine:
    def __init__(self, db_path: Path):
        self.db_path = Path(db_path)
        self.scientific_root = Path(os.environ.get("P5_SCIENTIFIC_ROOT_DIR", "/opt/p5/scientific-root-20"))
        self.artifact_root = Path(os.environ.get("P5_EXECUTION_ARTIFACT_ROOT", "/data/k3/research/private-alpha-execution"))
        self.evaluator_path = Path(os.environ.get("P5_EVALUATOR_FILE", str(_BUNDLE / "quant/p5_track3/t1_wave1_evaluator.py")))

    def _open(self) -> apsw.Connection:
        con = apsw.Connection(str(self.db_path))
        con.set_busy_timeout(2000)
        con.execute("PRAGMA foreign_keys=ON")
        return con

    def _proposal(self, con: apsw.Connection, proposal_id: str) -> tuple[FrozenBindings, tuple[Any, ...]]:
        row = con.execute(
            "SELECT binding_sha256,binding_json,producer_session_id,expires_at,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?",
            (proposal_id,),
        ).fetchone()
        if not row:
            raise FailClosed("PROPOSAL_NOT_FOUND")
        bindings = FrozenBindings(**json.loads(row[1])).validate()
        if bindings.digest != row[0]:
            raise FailClosed("CANONICAL_BINDING_CORRUPT")
        return bindings, row

    @staticmethod
    def _kind(bindings: FrozenBindings) -> str:
        return "W1" if bindings.wave_id is not None else "T1"

    def _scientific_observations(self, bindings: FrozenBindings) -> dict[str, Any]:
        manifest_path = self.scientific_root / "P5_FROZEN_SCIENTIFIC_VERIFY_SET_20_V1.json"
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise FailClosed("SCIENTIFIC_ROOT_MANIFEST_UNAVAILABLE") from exc
        objects = manifest.get("objects")
        if manifest.get("required_count") != 20 or not isinstance(objects, list) or len(objects) != 20:
            raise FailClosed("SCIENTIFIC_ROOT_COUNT_MISMATCH")
        if os.environ.get("P5_SYNTHETIC_MODE") != "1" and os.access(self.scientific_root, os.W_OK):
            raise FailClosed("SCIENTIFIC_ROOT_DAEMON_WRITABLE")
        by_field: dict[str, str] = {}
        observed = []
        for item in objects:
            path = self.scientific_root / Path(item["staged_path"]).name
            if path.is_symlink() or not path.is_file():
                raise FailClosed("SCIENTIFIC_ROOT_OBJECT_MISSING")
            actual = _file_sha256(path)
            if actual != item.get("sha256") or path.stat().st_size != item.get("size"):
                raise FailClosed("SCIENTIFIC_ROOT_OBJECT_DRIFT")
            observed.append({"name": path.name, "sha256": actual, "size": path.stat().st_size})
            if item.get("template_field"):
                by_field[item["template_field"]] = actual
        expected_pairs = {
            "allowed_t1_prereg_hash": bindings.prereg_sha256,
            "allowed_dataset_manifest_hash": bindings.dataset_manifest_sha256,
            "allowed_revision_hash": bindings.revision_lineage_sha256,
            "allowed_pit_rule_hash": bindings.universe_rule_sha256,
            "allowed_integrity_void_contract_hash": bindings.validation_contract_sha256,
        }
        if self._kind(bindings) == "W1":
            expected_pairs.update({
                "allowed_candidate_list_hash": bindings.candidate_list_sha256,
                "allowed_candidate_grammar_hash": bindings.candidate_grammar_sha256,
                "allowed_enumerator_hash": bindings.enumerator_sha256,
                "allowed_evaluation_order_hash": bindings.evaluation_order_sha256,
                "allowed_scientific_contract_hash": bindings.executable_contract_sha256,
            })
        if any(by_field.get(key) != value for key, value in expected_pairs.items()):
            raise FailClosed("FROZEN_SCIENTIFIC_BINDING_DRIFT")
        matrix = self.scientific_root / "P5_P3_T1_PRECONDITION_MATRIX_V4.md"
        if _file_sha256(matrix) != T1_MATRIX_SHA256:
            raise FailClosed("T1_PRECONDITION_MATRIX_DRIFT")
        evaluator_hash = _file_sha256(self.evaluator_path)
        if evaluator_hash != bindings.evaluator_sha256:
            raise FailClosed("EVALUATOR_HASH_DRIFT")
        evaluator.enforce_i12_source(self.evaluator_path)
        if self._kind(bindings) == "W1":
            candidate_path = self.scientific_root / "P5_P3_H0_DISCOVERY_WAVE1_CANDIDATE_LIST_V2.json"
            order_path = self.scientific_root / "P5_P3_H0_WAVE1_EVALUATION_ORDER_SUBOBJECT_V1.json"
            candidates = json.loads(candidate_path.read_text(encoding="utf-8"))
            order = json.loads(order_path.read_text(encoding="utf-8"))
            ids = [item.get("candidate_id") for item in candidates.get("candidates", [])]
            if candidates.get("candidate_count") != 174 or len(ids) != 174 or len(set(ids)) != 174:
                raise FailClosed("W1_CANDIDATE_COUNT_MISMATCH")
            if candidates.get("evaluation_order") != order or len(order) != 174 or set(order) != set(ids):
                raise FailClosed("W1_EVALUATION_ORDER_DRIFT")
        return {
            "manifest_sha256": _file_sha256(manifest_path),
            "objects": observed,
            "evaluator_sha256": evaluator_hash,
            "matrix_sha256": T1_MATRIX_SHA256,
        }

    def _state_rows(self, con: apsw.Connection) -> list[tuple[Any, ...]]:
        return list(con.execute(
            "SELECT amendment_id,amendment_sha256,authorization_mode,state FROM amendment_registrations ORDER BY registration_ordinal"
        ))

    def _t1_seal(self, con: apsw.Connection) -> tuple[Any, ...] | None:
        return con.execute(
            "SELECT result_sha256,result_state,proposal_id FROM sealed_results WHERE result_kind='T1' ORDER BY daemon_recorded_at LIMIT 1"
        ).fetchone()

    def _row_map(self, kind: str, scientific: Mapping[str, Any], adapter: Mapping[str, Any], t1_seal: tuple[Any, ...] | None) -> list[dict[str, Any]]:
        rows = [
            ("PC1", "PASS", "EXACT_C_D_ROOT_A_B_AND_AUTHORITY_FSM", "PC1_AUTHORITY_STAGE_FAIL"),
            ("PC2", "PASS", "FROZEN_SOURCE_TRANSPORT_HASH", "PC2_SOURCE_FREEZE_FAIL"),
            ("PC3", "PASS", "PREREG_ESTIMAND_AND_PIT_BINDINGS", "PC3_ESTIMAND_BINDING_FAIL"),
            ("PC4", "PASS", "FROZEN_EVALUATOR_AND_HAC_CONTRACT", "PC4_EVALUATOR_CONTRACT_FAIL"),
            ("PC5", "PASS", "HONEST_GROSS_PRIMARY_AND_DECLARED_NET_UNAVAILABLE", "PC5_COST_DECLARATION_FAIL"),
            ("PC6", "PASS", "PC6_MANIFEST_LINEAGE_AND_INPUT_AVAILABILITY", "PC6_DATA_FAIL"),
            ("PC7", "PASS", "ZERO_LLM_EVALUATOR_IDENTITY", "PC7_EVALUATOR_FAIL"),
            ("PC8", "PASS", "INTEGRITY_VOID_CONTRACT_BINDING", "PC8_INTEGRITY_FAIL"),
            ("PC9", "PASS", "NOT_APPLICABLE_H1", "PC9_SCOPE_FAIL"),
        ]
        result = [{"row_id": row, "status": status, "predicate": predicate, "fail_closed_code": code} for row, status, predicate, code in rows]
        if kind == "W1":
            result.extend([
                {"row_id": "W1-T1-FIRST", "status": "PASS" if t1_seal and t1_seal[1] != "TEST_VOIDED" else "FAIL", "predicate": "SEALED_NON_VOID_T1", "fail_closed_code": "W1_T1_SEAL_REQUIRED"},
                {"row_id": "W1-174", "status": "PASS", "predicate": "EXACT_LIST_GRAMMAR_ENUMERATOR_ORDER_174", "fail_closed_code": "W1_FROZEN_SCOPE_DRIFT"},
                {"row_id": "W1-RESOURCE", "status": "PASS", "predicate": "SIGNED_RESOURCE_POLICY_EXACT", "fail_closed_code": "W1_RESOURCE_POLICY_DRIFT"},
            ])
        return result

    def preconditions_evaluate(self, proposal_id: str, ctx: DaemonContext, db_verify: Mapping[str, Any]) -> dict[str, Any]:
        ctx.validate()
        if db_verify.get("status") != "PASS":
            raise FailClosed("DB_VERIFY_FAILED")
        read = self._open()
        try:
            bindings, row = self._proposal(read, proposal_id)
            last = read.execute("SELECT to_state FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1", (proposal_id,)).fetchone()
            if not last or last[0] != "PROPOSED":
                raise FailClosed("PRECONDITIONS_REQUIRE_PROPOSED")
            if parse_utc(ctx.recorded_at) >= parse_utc(row[3]):
                raise FailClosed("AUTHORITY_PROPOSAL_EXPIRED")
            if self._state_rows(read) != list(AMENDMENT_IDENTITIES):
                raise FailClosed("EXACT_C_D_ROOT_A_B_APPLIED_REQUIRED")
            root_resource = read.execute(
                "SELECT resource_policy_sha256 FROM owner_conditional_delegations WHERE state='ACTIVE'"
            ).fetchone()
            if not root_resource:
                raise FailClosed("ACTIVE_ROOT_DELEGATION_REQUIRED")
            if read.execute("SELECT 1 FROM owner_delegation_revocations").fetchone():
                raise FailClosed("DELEGATION_REVOKED")
            kind = self._kind(bindings)
            if kind == "T1" and read.execute("SELECT 1 FROM label_access_ledger").fetchone():
                raise FailClosed("T1_FIRST_LABEL_ACCESS_ALREADY_CONSUMED")
            if kind == "W1" and read.execute("SELECT 1 FROM label_access_ledger WHERE access_kind='W1'").fetchone():
                raise FailClosed("W1_LABEL_ACCESS_ALREADY_STARTED")
            t1_seal = self._t1_seal(read)
            if kind == "W1" and (not t1_seal or t1_seal[1] == "TEST_VOIDED"):
                raise FailClosed("W1_T1_SEAL_REQUIRED")
        finally:
            read.close()
        scientific = self._scientific_observations(bindings)
        adapter = PC6ExecutionAdapter(bindings).observe_outcome_free()
        if kind == "W1":
            policy = bindings.resource_scope
            if resource_policy_sha256(policy) != row[4] or row[4] != root_resource[0]:
                raise FailClosed("W1_RESOURCE_POLICY_DRIFT")
        row_map = self._row_map(kind, scientific, adapter, t1_seal)
        if any(item["status"] != "PASS" for item in row_map):
            raise FailClosed(next(item["fail_closed_code"] for item in row_map if item["status"] != "PASS"))
        evidence = {
            "schema": "p5-machine-precondition-evidence/v1",
            "proposal_id": proposal_id,
            "kind": kind,
            "binding_sha256": bindings.digest,
            "daemon_recorded_at": ctx.recorded_at,
            "db_verify": {"status": db_verify.get("status"), "integrity_check": db_verify.get("integrity_check"), "authority_verify": db_verify.get("authority_verify")},
            "amendment_state": [list(item) for item in AMENDMENT_IDENTITIES],
            "scientific": scientific,
            "data_availability": adapter,
            "t1_first": {"sealed_t1_sha256": t1_seal[0] if t1_seal else None, "sealed_t1_state": t1_seal[1] if t1_seal else None},
            "signed_resource_policy_sha256": root_resource[0] if kind == "W1" else None,
            "matrix_rows": row_map,
            "outcomes_read": False,
        }
        evidence_json = canonical_json(evidence)
        evidence_sha = _sha_bytes(evidence_json.encode("utf-8"))
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            current_bindings, current_row = self._proposal(con, proposal_id)
            latest = con.execute("SELECT to_state FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1", (proposal_id,)).fetchone()
            if current_bindings.digest != bindings.digest or not latest or latest[0] != "PROPOSED":
                raise FailClosed("PRECONDITION_REVALIDATION_FAILED")
            if self._state_rows(con) != list(AMENDMENT_IDENTITIES):
                raise FailClosed("PRECONDITION_REVALIDATION_FAILED")
            current_root_resource = con.execute(
                "SELECT resource_policy_sha256 FROM owner_conditional_delegations WHERE state='ACTIVE'"
            ).fetchone()
            if not current_root_resource or (kind == "W1" and current_row[4] != current_root_resource[0]):
                raise FailClosed("PRECONDITION_REVALIDATION_FAILED")
            if con.execute("SELECT 1 FROM owner_delegation_revocations").fetchone():
                raise FailClosed("DELEGATION_REVOKED")
            event_sha = _sha_json({"proposal_id": proposal_id, "to": "PRECONDITIONS_PASS", "evidence_sha256": evidence_sha, "sequence": ctx.ledger_sequence})
            con.execute(
                "INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",
                (proposal_id, "PROPOSED", "PRECONDITIONS_PASS", ctx.recorded_at, ctx.ledger_sequence, ctx.session_id, ctx.peer_uid, event_sha, current_row[4]),
            )
            transition_id = con.last_insert_rowid()
            con.execute("INSERT INTO precondition_evidence VALUES(?,?,?,?,?)", (evidence_sha, proposal_id, evidence_json, transition_id, ctx.recorded_at))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit():
                con.execute("ROLLBACK")
            raise
        finally:
            con.close()
        return {"status": "PASS", "proposal_id": proposal_id, "state": "PRECONDITIONS_PASS", "precondition_evidence_sha256": evidence_sha}

    def _authority_applied(self, con: apsw.Connection, proposal_id: str) -> None:
        row = con.execute("SELECT to_state FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1", (proposal_id,)).fetchone()
        if not row or row[0] != "APPLIED":
            raise FailClosed("AUTHORITY_NOT_APPLIED")
        evidence = con.execute("SELECT 1 FROM precondition_evidence WHERE proposal_id=?", (proposal_id,)).fetchone()
        if not evidence:
            raise FailClosed("MACHINE_PRECONDITION_EVIDENCE_ABSENT")
        if con.execute("SELECT 1 FROM delegation_redemptions r JOIN owner_delegation_revocations v USING(delegation_id) WHERE r.child_proposal_id=?", (proposal_id,)).fetchone():
            raise FailClosed("DELEGATION_REVOKED")

    def _reconcile_and_open_attempt(self, proposal_id: str, bindings: FrozenBindings, kind: str, ctx: DaemonContext) -> tuple[str, str, int, str | None]:
        logical_id = "trial-" + _sha_json({"proposal_id": proposal_id, "binding": bindings.digest})[:32]
        candidate_hash = bindings.candidate_list_sha256 or ("0" * 64)
        boot = _boot_id()
        now_ns = _monotonic_ns()
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            self._authority_applied(con, proposal_id)
            existing = con.execute("SELECT logical_trial_id,candidate_list_sha256 FROM logical_trials WHERE grant_proposal_id=?", (proposal_id,)).fetchone()
            if existing:
                if existing[0] != logical_id or existing[1] != candidate_hash:
                    raise FailClosed("NEW_CANDIDATE_LIST_REQUIRES_NEW_GRANT")
            else:
                con.execute("INSERT INTO logical_trials VALUES(?,?,?)", (logical_id, proposal_id, candidate_hash))
            if con.execute("SELECT 1 FROM sealed_results WHERE proposal_id=?", (proposal_id,)).fetchone():
                raise FailClosed("DUPLICATE_TERMINAL_RESULT")
            running = con.execute(
                "SELECT a.attempt_id,e.boot_id,e.daemon_pid,e.monotonic_ns FROM trial_attempts a JOIN trial_attempt_events e ON e.attempt_id=a.attempt_id AND e.event_ordinal=1 LEFT JOIN trial_attempt_events t ON t.attempt_id=a.attempt_id AND t.event_ordinal=2 WHERE a.logical_trial_id=? AND t.attempt_id IS NULL ORDER BY a.attempt_ordinal DESC LIMIT 1",
                (logical_id,),
            ).fetchone()
            if running:
                if running[1] != boot:
                    raise FailClosed("RUNNING_ATTEMPT_BOOT_ID_CHANGED_OWNER_ACTION_REQUIRED")
                if Path(f"/proc/{running[2]}").exists() or running[2] == os.getpid():
                    raise FailClosed("CONCURRENT_DUPLICATE_EXECUTE")
                elapsed = max(0, now_ns - int(running[3]))
                con.execute("INSERT INTO trial_attempt_events VALUES(?,?,?,?,?,?,?,?,?,?)", ("attempt-event-" + _sha_json({"a": running[0], "state": "ATTEMPT_VOID"})[:32], running[0], 2, "ATTEMPT_VOID", boot, os.getpid(), now_ns, elapsed, None, ctx.recorded_at))
                con.execute("COMMIT")
                raise FailClosed("UNSEALED_CRASH_OWNER_ACTION_REQUIRED")
            ordinal = int(con.execute("SELECT coalesce(max(attempt_ordinal),0)+1 FROM trial_attempts WHERE logical_trial_id=?", (logical_id,)).fetchone()[0])
            attempt_id = "attempt-" + _sha_json({"logical": logical_id, "ordinal": ordinal})[:32]
            con.execute("INSERT INTO trial_attempts VALUES(?,?,?,?,?)", (attempt_id, logical_id, ordinal, "RUNNING", None))
            con.execute("INSERT INTO trial_attempt_events VALUES(?,?,?,?,?,?,?,?,?,?)", ("attempt-event-" + _sha_json({"a": attempt_id, "state": "RUNNING"})[:32], attempt_id, 1, "RUNNING", boot, os.getpid(), now_ns, None, None, ctx.recorded_at))
            checkpoint = con.execute(
                "SELECT e.checkpoint_sha256 FROM trial_attempts a JOIN trial_attempt_events e ON e.attempt_id=a.attempt_id AND e.event_ordinal=2 WHERE a.logical_trial_id=? AND e.state='ATTEMPT_VOID' AND e.checkpoint_sha256 IS NOT NULL ORDER BY a.attempt_ordinal DESC LIMIT 1",
                (logical_id,),
            ).fetchone()
            if kind == "W1":
                policy_hash = resource_policy_sha256(bindings.resource_scope)
                cumulative = self._cumulative_ns(con, logical_id)
                con.execute("INSERT INTO wave_resource_events VALUES(?,?,?,?,?,?,?,?)", ("resource-" + _sha_json({"a": attempt_id, "k": "start"})[:32], proposal_id, logical_id, attempt_id, "ATTEMPT_STARTED", policy_hash, cumulative, ctx.recorded_at))
            con.execute("COMMIT")
            return logical_id, attempt_id, ordinal, checkpoint[0] if checkpoint else None
        except BaseException:
            if not con.getautocommit():
                con.execute("ROLLBACK")
            raise
        finally:
            con.close()

    @staticmethod
    def _cumulative_ns(con: apsw.Connection, logical_id: str) -> int:
        return int(con.execute(
            "SELECT coalesce(sum(e.active_elapsed_ns),0) FROM trial_attempts a JOIN trial_attempt_events e ON e.attempt_id=a.attempt_id AND e.event_ordinal=2 WHERE a.logical_trial_id=?",
            (logical_id,),
        ).fetchone()[0])

    def _durable_artifact(self, category: str, value: Any) -> tuple[str, str, int]:
        data = evaluator.canonical_bytes(value)
        digest = _sha_bytes(data)
        directory = self.artifact_root / category
        directory.mkdir(parents=True, exist_ok=True)
        os.chmod(self.artifact_root, 0o700)
        os.chmod(directory, 0o700)
        target = directory / f"{digest}.json"
        try:
            fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError as exc:
            raise FailClosed("DUPLICATE_WRITE_ONCE_ARTIFACT") from exc
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(data)
                stream.flush()
                os.fsync(stream.fileno())
            if os.name == "nt" and os.environ.get("P5_SYNTHETIC_MODE") == "1":
                # Windows synthetic transport has no directory-fsync API.
                # Production Linux always executes the fsync branch below.
                pass
            else:
                dirfd = os.open(directory, os.O_RDONLY)
                try:
                    os.fsync(dirfd)
                finally:
                    os.close(dirfd)
        except BaseException:
            raise
        if category == "results" and os.environ.get("P5_TEST_CRASH_AFTER_ARTIFACT_FSYNC") == "1":
            if os.environ.get("P5_SYNTHETIC_MODE") != "1":
                raise FailClosed("FAULT_INJECTION_FORBIDDEN")
            os._exit(86)
        return digest, f"{category}/{digest}.json", len(data)

    def _freeze_inputs(self, features: Mapping[str, Any], kind: str, order: list[str] | None) -> tuple[Any, str]:
        cohorts = features.get("cohorts")
        if not isinstance(cohorts, list) or not cohorts:
            raise FailClosed("PIT_FEATURE_COHORTS_UNAVAILABLE")
        if kind == "T1":
            frozen = [evaluator.freeze_quintile_weights({key: np.float64(value) for key, value in row.get("features", {}).items()}) for row in cohorts]
        else:
            frozen = {}
            assert order is not None
            for candidate_id in order:
                items = []
                for row in cohorts:
                    candidate_features = row.get("candidate_features", {}).get(candidate_id)
                    if not isinstance(candidate_features, dict):
                        raise FailClosed("W1_CANDIDATE_FEATURE_MISSING")
                    items.append(evaluator.freeze_quintile_weights({key: np.float64(value) for key, value in candidate_features.items()}))
                frozen[candidate_id] = items
        return frozen, _sha_json(_json_safe(frozen))

    def _mark_label_access(self, proposal_id: str, logical_id: str, attempt_id: str, kind: str, bindings: FrozenBindings, frozen_hash: str, ctx: DaemonContext, resume: bool) -> str | None:
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            self._authority_applied(con, proposal_id)
            existing = con.execute("SELECT frozen_weight_set_sha256,t1_seal_sha256 FROM label_access_ledger WHERE logical_trial_id=? AND access_kind=?", (logical_id, kind)).fetchone()
            if existing:
                if not resume or existing[0] != frozen_hash or kind != "W1":
                    raise FailClosed("LABEL_ACCESS_ALREADY_RECORDED")
                con.execute("COMMIT")
                return existing[1]
            t1 = self._t1_seal(con) if kind == "W1" else None
            if kind == "W1" and (not t1 or t1[1] == "TEST_VOIDED"):
                raise FailClosed("W1_T1_SEAL_REQUIRED")
            access_id = "label-access-" + _sha_json({"logical": logical_id, "kind": kind})[:32]
            con.execute("INSERT INTO label_access_ledger VALUES(?,?,?,?,?,?,?,?,?,?)", (access_id, proposal_id, logical_id, attempt_id, kind, bindings.digest, bindings.evaluator_sha256, frozen_hash, t1[0] if t1 else None, ctx.recorded_at))
            con.execute("COMMIT")
            return t1[0] if t1 else None
        except BaseException:
            if not con.getautocommit():
                con.execute("ROLLBACK")
            raise
        finally:
            con.close()

    @staticmethod
    def _outcome_cohorts(outcomes: Mapping[str, Any]) -> dict[str, list[dict[str, Mapping[str, np.float64]] | None]]:
        """F03: horizon-keyed label streams; a cohort inadmissible for a horizon
        carries None and can never enter that horizon's estimator."""
        cohorts = outcomes.get("cohorts", [])
        keys: set[str] = set()
        for cohort in cohorts:
            keys |= set(cohort.get("labels_by_horizon", {}))
        result: dict[str, list[dict[str, Mapping[str, np.float64]] | None]] = {}
        for key in sorted(keys):
            rows_list: list[dict[str, Mapping[str, np.float64]] | None] = []
            for cohort in cohorts:
                block = cohort.get("labels_by_horizon", {}).get(key)
                if block is None:
                    rows_list.append(None)
                    continue
                rows = {}
                for symbol, values in block.items():
                    rows[symbol] = {field: np.float64(values[field])
                                    for field in ("TOTAL", "SPOT", "TERM", "FUNDING")}
                rows_list.append(rows)
            result[key] = rows_list
        return result

    @staticmethod
    def _leg_contributions(frozen_row: Mapping[str, Any],
                           gate: "evaluator.LabelGate") -> tuple[np.float64, np.float64]:
        """F06: actual Q1 (positive-weight) and Q5 (negative-weight) leg
        contributions from the frozen signed weights and gated labels."""
        long_r = np.float64(0.0)
        short_r = np.float64(0.0)
        for symbol, weight in frozen_row["weights"].items():
            row = gate.read(symbol)
            if row is None:
                continue
            w = np.float64(weight)
            contribution = np.float64(w * np.float64(row["TOTAL"]))
            if w > 0:
                long_r = np.float64(long_r + contribution)
            elif w < 0:
                short_r = np.float64(short_r + contribution)
        return long_r, short_r

    def _complete_seal(self, proposal_id: str, logical_id: str, attempt_id: str, kind: str, bindings: FrozenBindings, result: Any, result_state: str | None, start_ns: int, ctx: DaemonContext) -> str:
        digest, relpath, size = self._durable_artifact("results", result)
        end_ns = _monotonic_ns()
        elapsed = max(0, end_ns - start_ns)
        boot = _boot_id()
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            self._authority_applied(con, proposal_id)
            if con.execute("SELECT 1 FROM sealed_results WHERE proposal_id=?", (proposal_id,)).fetchone():
                raise FailClosed("DUPLICATE_TERMINAL_SEAL")
            con.execute("INSERT INTO trial_attempt_events VALUES(?,?,?,?,?,?,?,?,?,?)", ("attempt-event-" + _sha_json({"a": attempt_id, "state": "COMPLETED"})[:32], attempt_id, 2, "COMPLETED", boot, os.getpid(), end_ns, elapsed, None, ctx.recorded_at))
            con.execute("INSERT INTO sealed_results VALUES(?,?,?,?,?,?,?,?,?,?,?)", (digest, kind, proposal_id, logical_id, attempt_id, relpath, size, result_state, bindings.digest, bindings.evaluator_sha256, ctx.recorded_at))
            if kind == "W1":
                cumulative = self._cumulative_ns(con, logical_id)
                con.execute("INSERT INTO wave_resource_events VALUES(?,?,?,?,?,?,?,?)", ("resource-" + _sha_json({"a": attempt_id, "k": "close"})[:32], proposal_id, logical_id, attempt_id, "ATTEMPT_CLOSED", resource_policy_sha256(bindings.resource_scope), cumulative, ctx.recorded_at))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit():
                con.execute("ROLLBACK")
            raise
        finally:
            con.close()
        path = self.artifact_root / relpath
        if not path.is_file() or path.stat().st_size != size or _file_sha256(path) != digest:
            raise FailClosed("SEALED_RESULT_READBACK_FAILED")
        return digest

    def _resource_checkpoint(self, proposal_id: str, logical_id: str, attempt_id: str, bindings: FrozenBindings, payload: Any, start_ns: int, ctx: DaemonContext) -> str:
        digest, _, _ = self._durable_artifact("checkpoints", payload)
        end_ns = _monotonic_ns()
        elapsed = max(0, end_ns - start_ns)
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            con.execute("INSERT INTO trial_attempt_events VALUES(?,?,?,?,?,?,?,?,?,?)", ("attempt-event-" + _sha_json({"a": attempt_id, "state": "ATTEMPT_VOID"})[:32], attempt_id, 2, "ATTEMPT_VOID", _boot_id(), os.getpid(), end_ns, elapsed, digest, ctx.recorded_at))
            cumulative = self._cumulative_ns(con, logical_id)
            policy_hash = resource_policy_sha256(bindings.resource_scope)
            con.execute("INSERT INTO wave_resource_events VALUES(?,?,?,?,?,?,?,?)", ("resource-" + _sha_json({"a": attempt_id, "k": "checkpoint"})[:32], proposal_id, logical_id, attempt_id, "CHECKPOINT_SEALED", policy_hash, cumulative, ctx.recorded_at))
            con.execute("INSERT INTO wave_resource_events VALUES(?,?,?,?,?,?,?,?)", ("resource-" + _sha_json({"a": attempt_id, "k": "close"})[:32], proposal_id, logical_id, attempt_id, "ATTEMPT_CLOSED", policy_hash, cumulative, ctx.recorded_at))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit():
                con.execute("ROLLBACK")
            raise
        finally:
            con.close()
        return digest

    def trial_execute(self, proposal_id: str, ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate()
        read = self._open()
        try:
            bindings, _ = self._proposal(read, proposal_id)
            self._authority_applied(read, proposal_id)
        finally:
            read.close()
        kind = self._kind(bindings)
        self._scientific_observations(bindings)
        adapter = PC6ExecutionAdapter(bindings)
        adapter.observe_outcome_free()
        features = adapter.load_features()
        order = None
        candidates_by_id: dict[str, Any] = {}
        if kind == "W1":
            candidate_file = json.loads((self.scientific_root / "P5_P3_H0_DISCOVERY_WAVE1_CANDIDATE_LIST_V2.json").read_text(encoding="utf-8"))
            order = json.loads((self.scientific_root / "P5_P3_H0_WAVE1_EVALUATION_ORDER_SUBOBJECT_V1.json").read_text(encoding="utf-8"))
            candidates_by_id = {item["candidate_id"]: item for item in candidate_file["candidates"]}
            if len(order) != 174 or set(order) != set(candidates_by_id):
                raise FailClosed("W1_FROZEN_SCOPE_DRIFT")
        frozen, frozen_hash = self._freeze_inputs(features, kind, order)
        # F07: all outcome-free DEVELOPMENT_REJECTED states are computed and the
        # rejected/evaluable set is frozen BEFORE any W1 label access (marker
        # below).  Rules exactly per W1 contract section 6, in frozen order.
        rejection_by_candidate: dict[str, str | None] = {}
        admissible_by_horizon: dict[int, list[int]] = {}
        rejection_set_sha256 = None
        if kind == "W1":
            cohort_rows = features["cohorts"]
            for horizon in (8, 24, 168):
                admissible_by_horizon[horizon] = [
                    index for index, row in enumerate(cohort_rows)
                    if mat.w1_admissible(int(row["decision_us"]), horizon)]
            seen_candidate_hashes: set[str] = set()
            seen_weight_paths: set[str] = set()
            assert order is not None
            for candidate_id in order:
                candidate = candidates_by_id[candidate_id]
                horizon = int(candidate["holding_horizon_hours"])
                admissible = admissible_by_horizon[horizon]
                feature_rows = [cohort_rows[index].get("candidate_features", {}).get(candidate_id, {})
                                for index in admissible]
                frozen_rows = [frozen[candidate_id][index] for index in admissible]
                rejection_by_candidate[candidate_id] = mat.development_rejection_reason(
                    candidate, feature_rows, frozen_rows,
                    seen_candidate_hashes, seen_weight_paths)
            rejection_set_sha256 = _sha_json(rejection_by_candidate)
        logical_id, attempt_id, ordinal, checkpoint_sha = self._reconcile_and_open_attempt(proposal_id, bindings, kind, ctx)
        hold_ms = os.environ.get("P5_TEST_HOLD_AFTER_ATTEMPT_OPEN_MS")
        if hold_ms is not None:
            if os.environ.get("P5_SYNTHETIC_MODE") != "1":
                raise FailClosed("FAULT_INJECTION_FORBIDDEN")
            time.sleep(int(hold_ms) / 1000.0)
        start_ns = _monotonic_ns()
        resume = checkpoint_sha is not None
        start_index = 0
        diagnostics: list[dict[str, Any]] = []
        if checkpoint_sha:
            checkpoint_path = self.artifact_root / "checkpoints" / f"{checkpoint_sha}.json"
            checkpoint = evaluator.read_checkpoint(checkpoint_path, checkpoint_sha)
            expected = {"logical_trial_id": logical_id, "binding_sha256": bindings.digest, "candidate_list_sha256": bindings.candidate_list_sha256, "evaluation_order_sha256": bindings.evaluation_order_sha256}
            if any(checkpoint.get(key) != value for key, value in expected.items()):
                raise FailClosed("CHECKPOINT_BINDING_MISMATCH")
            start_index = int(checkpoint.get("completed_prefix", -1))
            diagnostics = checkpoint.get("private_diagnostics", [])
            if start_index < 0 or start_index > 174 or len(diagnostics) != start_index:
                raise FailClosed("CHECKPOINT_PREFIX_INVALID")
        self._mark_label_access(proposal_id, logical_id, attempt_id, kind, bindings, frozen_hash, ctx, resume)
        # F01: outcomes are DERIVED by the TCB-pinned materializer inside the
        # daemon strictly after APPLIED + durable marker; no outcomes file.
        outcomes = adapter.derive_outcomes(marker_recorded=True)
        labels_by_horizon = self._outcome_cohorts(outcomes)
        if len(outcomes.get("cohorts", [])) != len(features["cohorts"]):
            raise FailClosed("PC6_COHORT_ALIGNMENT_MISMATCH")
        allowed_by_horizon = {key: int(value) for key, value in
                              features.get("allowed_label_end_us_by_horizon", {}).items()}
        label_end_by_horizon = {key: int(value) for key, value in
                                outcomes.get("label_end_us_by_horizon", {}).items()}
        if kind == "T1":
            labels = labels_by_horizon.get("8")
            if labels is None:
                raise FailClosed("PC6_T1_LABEL_STREAM_MISSING")
            allowed_end_us = allowed_by_horizon.get("8", -1)
            label_end_us = label_end_by_horizon.get("8", -1)
            components = []
            for frozen_row, label_row in zip(frozen, labels, strict=True):
                if frozen_row.get("state") != "FROZEN":
                    # F02: STRUCTURALLY_UNDEFINED is counted/reported, never
                    # gated (no LabelGate.open) and never enters the estimator.
                    components.append({"state": "STRUCTURALLY_UNDEFINED"})
                    continue
                if label_row is None:
                    raise FailClosed("PC6_T1_LABEL_COHORT_MISSING")
                gate = evaluator.LabelGate(label_row, allowed_end_us)
                gate.open(frozen_row, True, label_end_us)
                components.append(evaluator.evaluate_frozen_portfolio(frozen_row, gate))
            # F02: only OUTCOME_COMPLETE cohorts enter the gross series/HAC.
            series = np.asarray([item["TOTAL"] for item in components
                                 if item.get("state") == "OUTCOME_COMPLETE"], dtype=np.float64)
            if series.size == 0:
                raise FailClosed("T1_ESTIMATOR_EMPTY")
            synthetic_void = outcomes.get("synthetic_force_t1_integrity_void") is True
            if synthetic_void and os.environ.get("P5_SYNTHETIC_MODE") != "1":
                raise FailClosed("SYNTHETIC_INTEGRITY_VOID_MARKER_FORBIDDEN")
            artifact = evaluator.t1_result_artifact(
                series, components, integrity_pass=not synthetic_void
            )
            state = artifact["result_state"]
            if state not in RESULT_STATES:
                raise FailClosed("T1_RESULT_STATE_INVALID")
            sealed = self._complete_seal(proposal_id, logical_id, attempt_id, kind, bindings, {"schema": "p5-t1-sealed-result/v2", "proposal_id": proposal_id, "binding_sha256": bindings.digest, "evaluator_sha256": bindings.evaluator_sha256, "materializer_sha256": mat.materializer_sha256(), "result": artifact}, state, start_ns, ctx)
            return {"status": "SEALED", "proposal_id": proposal_id, "logical_trial_id": logical_id, "attempt_id": attempt_id, "attempt_ordinal": ordinal, "sealed_artifact_sha256": sealed, "result_state": state}
        assert order is not None
        policy = bindings.resource_scope
        limit_ns = int(policy["wall_time_expiry_seconds"]) * 1_000_000_000
        con = self._open()
        try:
            prior_ns = self._cumulative_ns(con, logical_id)
        finally:
            con.close()
        for index in range(start_index, 174):
            synthetic_exhaustion = False
            test_after = os.environ.get("P5_TEST_EXHAUST_AFTER_CANDIDATES")
            if test_after is not None:
                if os.environ.get("P5_SYNTHETIC_MODE") != "1":
                    raise FailClosed("FAULT_INJECTION_FORBIDDEN")
                marker = self.artifact_root / ".synthetic-exhaustion-consumed"
                if index >= int(test_after) and not marker.exists():
                    marker.write_text("consumed\n", encoding="ascii")
                    synthetic_exhaustion = True
            if synthetic_exhaustion or prior_ns + max(0, _monotonic_ns() - start_ns) >= limit_ns:
